      quiz: [mc('«irse» =', ['to leave', 'to go (destination)'], 0), mc('Completion se needs…', ['a specific quantity', 'any noun'], 0), mc('«parecerse a» =', ['to resemble', 'to seem'], 0), mc('«ocuparse de» =', ['to take care of', 'to occupy'], 0), mc('«Se murió su abuelo» sounds…', ['natural/emotional', 'violent'], 0)]
