      quiz: [mc('de modo que + indicative =', ['consequence', 'purpose'], 0), mc('de modo que + subjunctive =', ['purpose', 'consequence'], 0), mc('«así que» introduces…', ['consequence', 'cause'], 0), mc('«conque» register:', ['colloquial', 'legal'], 0), mc('«luego» (logic) =', ['therefore', 'then later only'], 0)]
