      tables: [['tan… que', ['Structure', 'Example', 'English'], [['tan + adj. + que', 'Es tan caro que nadie lo compra.', 'It’s so expensive that nobody buys it.'], ['tan + adv. + que', 'Habla tan rápido que no le entiendo.', 'She speaks so fast I don’t understand her.'], ['tan + adj. + que (negative main → subj.)', 'No es tan difícil que no puedas hacerlo.', 'It isn’t so hard that you can’t do it.'], ['de tan + adj. + como + verb', 'De tan cansada como estaba, se durmió.', 'She was so tired she fell asleep.'], ['de lo + adj. + que + verb', 'No pude dormir de lo nerviosa que estaba.', 'I couldn’t sleep, I was so nervous.']], [1]]],
      rules: [['tan only before adjectives/adverbs', 'tan bonito, tan bien (not «tan mucho»)'], ['Negative main clause → subjunctive consequence', 'No es tan grave que haya que llamar al médico.'], ['Exclamative alternative', '¡Es tan amable!']],
