      tables: [['tanto… que', ['Structure', 'Example', 'English'], [['tanto/a + noun + que', 'Había tanta gente que no pudimos entrar.', 'There were so many people we couldn’t get in.'], ['tantos/as + noun + que', 'Tengo tantos deberes que no salgo.', 'I have so much homework I’m not going out.'], ['verb + tanto + que', 'Trabajó tanto que enfermó.', 'He worked so much that he got ill.'], ['tal + noun + que', 'Tenía tal hambre que se comió dos platos.', 'She was so hungry she ate two plates.'], ['cada… que (colloquial)', 'Dice cada cosa que…', 'He says such things that…']], [1]]],
      rules: [['tanto agrees with nouns', 'tanta agua, tantos coches'], ['After a verb: tanto (invariable)', 'Llovió tanto que…'], ['tal + noun (formal/strong)', 'Fue tal el éxito que repitieron.']],
      examples: [['Había tanto ruido que no podía pensar.', 'There was so much noise I couldn’t think.'], ['Comí tanto que me dolía la barriga.', 'I ate so much my stomach hurt.'], ['Tenemos tantas ganas que no podemos esperar.', 'We’re so eager we can’t wait.'], ['Fue tal el escándalo que dimitió.', 'The scandal was such that he resigned.'], ['Ha llovido tanto que el río se ha desbordado.', 'It has rained so much that the river has overflowed.'], ['Tenía tal sueño que se durmió de pie.', 'He was so sleepy he fell asleep standing up.']],
      mistakes: [['tanto gente', 'tanta gente'], ['Trabajó tanta que…', 'Trabajó tanto que…'], ['Había tantas ruido', 'Había tanto ruido']],
