      mistakes: [['De ahí que es…', 'De ahí que sea…'], ['Para que (as consequence): Llovió, para que no salimos.', 'Llovió, así que no salimos.'], ['A fin de que tiene…', 'A fin de que tenga…']],
      practice: [mc('Purpose or consequence? «Ahorro para que mis hijos estudien.»', ['purpose', 'consequence'], 0), mc('Formal consequence + subjunctive:', ['de ahí que', 'así que'], 0), fl('Hubo retrasos; de ahí que ___ (subir) el presupuesto.', ['subiera', 'subiese', 'suba']), mc('Intensity consequence:', ['tan… que', 'a fin de'], 0), mc('Colloquial consequence:', ['total, que…', 'con objeto de'], 0), tr('There was no budget; hence the project was postponed.', ['no había presupuesto; de ahí que se aplazara el proyecto', 'no había presupuesto, de ahí que se aplazara el proyecto', 'no había presupuesto; por eso se aplazó el proyecto'])],
